class Fib {
    int idx;
    int a, b;
public:
    Fib(int n): idx(n) {
        a = 0; b = 1;
        for (int i = 2; i <= n; ++i) {
            int c = a + b; a = b; b = c;
        }
    }
    int operator*() const { return b; }
    Fib& operator++() {
        int c = a + b; a = b; b = c; ++idx;
        return *this;
    }
    bool operator!=(const Fib& o) const { return idx != o.idx; }
};

